154	// ---- [Manual entry] (also used to confirm / edit a photo estimate) ---------------------------------------------
155	function ManualMeal({
156	  source, initial, onSaved, onError, onDone,
157	}: {
158	  source: MealSource;
159	  initial?: { foodName: string; calories: number; proteinG: number; carbsG: number; fatG: number };
160	  onSaved: SavedFn;
161	  onError: ErrFn;
162	  onDone?: () => void;
163	}) {
164	  const [name, setName] = useState(initial?.foodName ?? '');
165	  const [cal, setCal] = useState(initial ? String(initial.calories) : '');
166	  const [p, setP] = useState(initial ? String(round1(initial.proteinG)) : '');
167	  const [c, setC] = useState(initial ? String(round1(initial.carbsG)) : '');
168	  const [f, setF] = useState(initial ? String(round1(initial.fatG)) : '');
169	  const [busy, setBusy] = useState(false);
170	
171	  const calories = cal.trim() === '0' ? 0 : parsePositiveInt(cal, 5000);
172	  const macros = [parseMacro(p), parseMacro(c), parseMacro(f)];
173	  const valid = name.trim().length > 0 && calories !== null && macros.every((x) => x !== null);
174	
175	  async function save() {
176	    setBusy(true);
177	    try {
178	      const r = await api.saveMealEntry({
179	        source, foodName: name.trim(), calories: calories!, proteinG: macros[0]!, carbsG: macros[1]!, fatG: macros[2]!,
180	      });
181	      onSaved(r.summary, `Saved "${r.saved.foodName}" (${r.saved.calories} kcal).`);
182	      setName(''); setCal(''); setP(''); setC(''); setF('');
183	      onDone?.();
184	    } catch (e) {
185	      onError(e);
186	    } finally {
187	      setBusy(false);
188	    }
189	  }
