210	function PhotoMeal({ onSaved, onError }: { onSaved: SavedFn; onError: ErrFn }) {
211	  const [estimate, setEstimate] = useState<PhotoEstimate | null>(null);
212	  const [busy, setBusy] = useState(false);
213	
214	  async function pick(camera: boolean) {
215	    try {
216	      if (camera && Platform.OS !== 'web') {
217	        const perm = await ImagePicker.requestCameraPermissionsAsync();
218	        if (!perm.granted) throw new ApiError(0, 'PERMISSION', 'Camera permission is needed to photograph a meal');
219	      }
220	      const opts: ImagePicker.ImagePickerOptions = { mediaTypes: ['images'], quality: 0.6 };
221	      const res = camera && Platform.OS !== 'web' ? await ImagePicker.launchCameraAsync(opts) : await ImagePicker.launchImageLibraryAsync(opts);
222	      if (res.canceled || !res.assets?.length) return;
223	      const asset = res.assets[0];
224	      setBusy(true);
225	      const form = new FormData();
226	      const type = asset.mimeType ?? 'image/jpeg';
227	      if (Platform.OS === 'web') {
228	        const blob = await (await fetch(asset.uri)).blob();
229	        form.append('image', blob, asset.fileName ?? 'meal.jpg');
230	      } else {
231	        form.append('image', { uri: asset.uri, name: asset.fileName ?? 'meal.jpg', type } as unknown as Blob);
232	      }
233	      setEstimate(await api.submitMealPhoto(form));
234	    } catch (e) {
235	      onError(e);
236	    } finally {
237	      setBusy(false);
238	    }
239	  }
240	
241	  return (
242	    <View style={{ marginTop: 8 }}>
243	      <Text style={s.muted}>
244	        Take a photo of your meal and CometFit will estimate the calories and macros. You can edit the estimate before saving.
