248	          <Button label={Platform.OS === 'web' ? 'Choose meal photo' : 'Take photo'} onPress={() => pick(true)} busy={busy} />
249	        </View>
250	        {Platform.OS !== 'web' ? (
251	          <View style={{ flex: 1 }}>
252	            <Button kind="secondary" label="From gallery" onPress={() => pick(false)} disabled={busy} />
253	          </View>
254	        ) : null}
255	      </Row>
256	      {estimate ? (
257	        <View style={{ marginTop: 8 }}>
258	          <Banner kind="info">{estimate.notice}</Banner>
259	          {estimate.foodItems.map((f) => (
260	            <Text key={f.foodName} style={s.muted}>
261	              • {f.foodName}: {f.calories} kcal (confidence {Math.round(f.confidence * 100)}%)
262	            </Text>
263	          ))}
264	          <ManualMeal
265	            key={estimate.draft.foodName + estimate.draft.calories}
266	            source="PHOTO"
267	            initial={estimate.draft}
268	            onSaved={onSaved}
269	            onError={onError}
270	            onDone={() => setEstimate(null)}
271	          />
272	        </View>
273	      ) : null}
274	    </View>
275	  );
276	}
