1	// Log In (Password + TOTP) — included by UC-1..UC-4 (D1 Fig 4.3); SD-4 "login (password + TOTP)".
2	// NFR Security: username + password + TOTP MFA. Sign-up for students: ASSUMPTIONS A-3.
3	// TD-1 (stage 2):
4	//   (1) after sign-up: "Add to authenticator app" (opens the otpauth link with the account filled in) and
5	//       "Copy setup key" as a backup;
6	//   (2) QR code of the setup key only on a larger screen (laptop browser), where a phone can scan it;
7	//   (3) "Remember this device for 30 days": on a remembered device, username + password only.
8	import * as Clipboard from 'expo-clipboard';
9	import React, { useEffect, useMemo, useState } from 'react';
10	import { Linking, ScrollView, Text, useWindowDimensions, View } from 'react-native';
11	import { api, ApiError } from '../api';
12	import { forgetRememberedDevice, getRememberedDevice, saveRememberedDevice } from '../deviceTrust';
13	import { isLargeScreen, isStillRemembered, type RememberedDevice } from '../logic';
14	import { qrMatrix } from '../qr';
15	import type { LoginResponse, Registration } from '../types';
16	import { Banner, Button, Card, Field, Row, s, Toggle } from '../ui';
17	
18	export default function LoginScreen({ onLoggedIn }: { onLoggedIn: (r: LoginResponse) => void }) {
19	  const [mode, setMode] = useState<'login' | 'register'>('login');
20	  const [username, setUsername] = useState('');
21	  const [password, setPassword] = useState('');
22	  const [code, setCode] = useState('');
23	  const [rememberDevice, setRememberDevice] = useState(false);
24	  const [remembered, setRemembered] = useState<RememberedDevice | null>(null);
25	  const [useCodeAnyway, setUseCodeAnyway] = useState(false);
26	  const [email, setEmail] = useState('');
27	  const [displayName, setDisplayName] = useState('');
28	  const [busy, setBusy] = useState(false);
29	  const [error, setError] = useState<string | null>(null);
30	  const [registered, setRegistered] = useState<Registration | null>(null);
31	
32	  // TD-1 (3): is this device remembered for the username being typed?
33	  useEffect(() => {
34	    let alive = true;
35	    getRememberedDevice(username).then((d) => alive && setRemembered(isStillRemembered(d) ? d : null));
36	    return () => {
37	      alive = false;
38	    };
39	  }, [username]);
40	
41	  const skipCode = remembered !== null && !useCodeAnyway;
42	
43	  async function login() {
44	    setError(null);
45	    setBusy(true);
46	    try {
47	      const r = await api.login({
48	        username,
49	        password,
50	        totpCode: skipCode ? undefined : code.trim(),
51	        rememberDevice: skipCode ? undefined : rememberDevice,
52	        deviceToken: remembered?.token,
53	      });
54	      if (r.deviceToken && r.trustedUntil) {
55	        await saveRememberedDevice(username, { token: r.deviceToken, trustedUntil: r.trustedUntil });
56	      }
57	      onLoggedIn(r);
58	    } catch (e) {
59	      if (skipCode && (e as ApiError).status === 401) {
60	        // Remembered device no longer accepted (expired, password changed, ...): ask for the code again.
61	        await forgetRememberedDevice(username);
62	        setRemembered(null);
63	        setError('Please enter the 6-digit code from your authenticator app.');
64	      } else {
65	        setError((e as ApiError).message);
66	      }
67	    } finally {
68	      setBusy(false);
69	    }
70	  }
71	
72	  async function register() {
73	    setError(null);
74	    setBusy(true);
75	    try {
76	      const r = await api.register({ username, password, email, displayName: displayName || undefined });
77	      setRegistered(r);
78	      setMode('login');
79	      setCode('');
80	    } catch (e) {
81	      setError((e as ApiError).message);
82	    } finally {
83	      setBusy(false);
84	    }
85	  }
86	
87	  return (
88	    <ScrollView contentContainerStyle={{ padding: 20, maxWidth: 480, width: '100%', alignSelf: 'center' }}>
89	      <View style={{ alignItems: 'center', marginVertical: 24 }}>
90	        <Text style={[s.h1, { fontSize: 30 }]}>CometFit</Text>
91	        <Text style={s.muted}>Healthy habits for student life</Text>
92	      </View>
93	
94	      {registered ? <AuthenticatorSetup registration={registered} /> : null}
95	
96	      <Card title={mode === 'login' ? 'Sign in' : 'Create a student account'}>
97	        {error ? <Banner kind="error">{error}</Banner> : null}
98	        <Field label="Username" value={username} onChangeText={setUsername} autoCapitalize="none" autoCorrect={false} testID="username" />
99	        <Field label="Password" value={password} onChangeText={setPassword} secureTextEntry testID="password" />
100	        {mode === 'login' ? (
101	          skipCode ? (
102	            <View style={{ marginBottom: 8 }}>
103	              <Text style={s.muted} testID="remembered-note">
104	                This device is remembered until {new Date(remembered!.trustedUntil).toLocaleDateString()}. No code needed.
105	              </Text>
106	              <Button kind="secondary" label="Use a code instead" onPress={() => setUseCodeAnyway(true)} />
107	            </View>
108	          ) : (
109	            <>
110	              <Field
111	                label="6-digit code from your authenticator app"
112	                value={code}
113	                onChangeText={setCode}
114	                keyboardType="number-pad"
115	                maxLength={6}
116	                testID="totp"
117	              />
118	              <Toggle label="Remember this device for 30 days" value={rememberDevice} onChange={setRememberDevice} />
119	            </>
120	          )
121	        ) : (
122	          <>
123	            <Field label="Email" value={email} onChangeText={setEmail} autoCapitalize="none" keyboardType="email-address" />
124	            <Field label="Display name (public)" value={displayName} onChangeText={setDisplayName} />
125	            <Text style={s.muted}>Password: at least 8 characters.</Text>
126	          </>
127	        )}
128	        {mode === 'login' ? (
129	          <Button
130	            label="Sign in"
131	            onPress={login}
132	            busy={busy}
133	            disabled={!username || !password || (!skipCode && code.trim().length !== 6)}
134	            testID="signin"
135	          />
136	        ) : (
137	          <Button label="Create account" onPress={register} busy={busy} disabled={!username || !password || !email} />
138	        )}
139	        <Button
140	          kind="secondary"
141	          label={mode === 'login' ? 'New student? Create an account' : 'Back to sign in'}
142	          onPress={() => {
143	            setError(null);
144	            setMode(mode === 'login' ? 'register' : 'login');
145	          }}
146	        />
147	      </Card>
148	      <Text style={[s.muted, { textAlign: 'center' }]}>
149	        CometFit is a general wellness app and does not diagnose or treat any medical condition.
150	      </Text>
151	    </ScrollView>
152	  );
153	}
154	
155	// ---- TD-1 (1) + (2): two-factor setup after sign-up ----------------------------------------------------------------
156	function AuthenticatorSetup({ registration }: { registration: Registration }) {
157	  const { width } = useWindowDimensions();
158	  const [note, setNote] = useState<{ kind: 'good' | 'warn'; text: string } | null>(null);
159	
160	  async function openAuthenticator() {
161	    try {
162	      await Linking.openURL(registration.otpauthUri);
163	    } catch {
164	      setNote({ kind: 'warn', text: 'No authenticator app opened. Use "Copy setup key" and paste it into your authenticator app.' });
165	    }
166	  }
167	  async function copyKey() {
168	    try {
169	      await Clipboard.setStringAsync(registration.totpSecret);
170	      setNote({ kind: 'good', text: 'Setup key copied. Paste it into your authenticator app.' });
171	    } catch {
172	      setNote({ kind: 'warn', text: 'Could not copy. Select the key below and copy it by hand.' });
173	    }
174	  }
175	
176	  return (
177	    <Card title="Set up two-factor sign-in">
178	      <Text style={s.body}>
179	        Account created for {registration.user.username}. Add CometFit to your authenticator app. You will be asked
180	        for its 6-digit code when you sign in on a new device.
181	      </Text>
182	      {note ? <Banner kind={note.kind}>{note.text}</Banner> : null}
183	      <Row>
184	        <View style={{ flex: 1 }}>
185	          <Button label="Add to authenticator app" onPress={openAuthenticator} testID="add-authenticator" />
186	        </View>
187	        <View style={{ flex: 1 }}>
188	          <Button kind="secondary" label="Copy setup key" onPress={copyKey} testID="copy-setup-key" />
189	        </View>
190	      </Row>
191	      {isLargeScreen(width) ? (
192	        <View style={{ alignItems: 'center', marginVertical: 8 }} testID="setup-qr">
193	          <Text style={s.muted}>Or scan this QR code with your phone's authenticator app:</Text>
194	          <SetupQrCode text={registration.otpauthUri} />
195	        </View>
196	      ) : null}
197	      <Text selectable style={[s.muted, { fontFamily: 'monospace', marginTop: 4 }]}>
198	        Setup key: {registration.totpSecret}
199	      </Text>
200	    </Card>
201	  );
202	}
203	
204	/** Draws the QR matrix with Views (works in the browser and on phones). */
205	function SetupQrCode({ text, cell = 5 }: { text: string; cell?: number }) {
206	  const rows = useMemo(() => qrMatrix(text), [text]);
207	  const quiet = cell * 4;
208	  return (
209	    <View style={{ backgroundColor: '#fff', padding: quiet, marginTop: 8 }} accessibilityLabel="Authenticator setup QR code">
210	      {rows.map((row, y) => (
211	        <View key={y} style={{ flexDirection: 'row' }}>
212	          {row.map((dark, x) => (
213	            <View key={x} style={{ width: cell, height: cell, backgroundColor: dark ? '#000' : '#fff' }} />
214	          ))}
215	        </View>
216	      ))}
217	    </View>
218	  );
219	}
