1	// Pure helpers used by the screens (unit-tested in __tests__/logic.test.ts).
2	import type { ModuleState } from './types';
3	
4	/** Progress 0..1 toward a goal (UC-1 "View Daily Summary & Goals"). */
5	export function progress(value: number, goal: number): number {
6	  if (!goal || goal <= 0) return 0;
7	  return Math.max(0, Math.min(1, value / goal));
8	}
9	
10	/** Water volume for N bottle refills (Proposal §4 "calculating water intake based on the number of refills"; SD-1). */
11	export function refillVolume(bottleSizeMl: number, refills: number): number {
12	  if (!Number.isFinite(bottleSizeMl) || !Number.isFinite(refills)) return 0;
13	  return Math.max(0, Math.round(bottleSizeMl * refills));
14	}
15	
16	/** Liters per US gallon, as in the team's LogWater.java. */
17	export const LITERS_PER_GALLON = 3.785412;
18	
19	/** Client preview of LogWater.enter's conversion: gallons -> liters, truncated to two decimals (server is authoritative). */
20	export function toLiters(amount: number, isLiter: boolean): number {
21	  const a = isLiter ? amount : amount * LITERS_PER_GALLON;
22	  return Math.floor(a * 100 + 1e-9) / 100;
23	}
24	
25	/** Parses a positive decimal amount (water in L or gal); null when empty, not a number, or <= 0. */
