1	// Client unit tests (run with `npm test`, Node's built-in runner with TypeScript type stripping).
2	import assert from 'node:assert/strict';
3	import { test } from 'node:test';
4	import {
5	  formatDuration, goalWarnings, isEnabled, parseMacro, parsePositiveAmount, parsePositiveInt, progress, refillVolume, toLiters,
6	} from '../src/logic.ts';
7	
8	// Team repo code LogWater.java / D2 §4.3 TC-1: 0.3 gal -> 1.13 L (truncated, not rounded)
9	test('water preview converts gallons to liters and truncates to two decimals like LogWater', () => {
10	  assert.equal(toLiters(0.3, false), 1.13);
11	  assert.equal(toLiters(0.5, true), 0.5);
12	  assert.equal(toLiters(0.759, true), 0.75);
13	  assert.equal(toLiters(0.29, true), 0.29);
14	  assert.equal(toLiters(1, false), 3.78);
15	});
16	
17	// D2 §4.1: negative or missing values are rejected
18	test('water amount parsing accepts positive decimals only', () => {
19	  assert.equal(parsePositiveAmount('0.5'), 0.5);
20	  assert.equal(parsePositiveAmount('1,25'), 1.25);
21	  assert.equal(parsePositiveAmount('.3'), 0.3);
22	  assert.equal(parsePositiveAmount('2'), 2);
23	  assert.equal(parsePositiveAmount(''), null);
24	  assert.equal(parsePositiveAmount('-0.3'), null);
25	  assert.equal(parsePositiveAmount('0'), null);
26	  assert.equal(parsePositiveAmount('abc'), null);
27	});
28	import { FakeSmartDevice, seeded } from '../src/smartDevice.ts';
29	import { deviceKey, isLargeScreen, isStillRemembered } from '../src/logic.ts';
30	import { qrMatrix } from '../src/qr.ts';
31	
32	// TD-1 (2): QR code only on a larger screen (laptop browser), not on the phone's own screen
33	test('QR code is shown only on larger screens', () => {
34	  assert.equal(isLargeScreen(390), false);   // phone
35	  assert.equal(isLargeScreen(767), false);
36	  assert.equal(isLargeScreen(768), true);
37	  assert.equal(isLargeScreen(1440), true);   // laptop browser
38	});
39	
40	// TD-1 (2): the QR encodes the otpauth setup link
41	test('QR matrix for the authenticator link is a square of modules with finder patterns', () => {
42	  const m = qrMatrix('otpauth://totp/CometFit:alice?secret=COMETFITALICE234&issuer=CometFit');
43	  assert.ok(m.length >= 21 && (m.length - 17) % 4 === 0);    // QR version size 17 + 4v
44	  assert.ok(m.every((row) => row.length === m.length));
45	  // top-left finder pattern: dark 7x7 border
46	  for (let i = 0; i < 7; i++) {
47	    assert.equal(m[0][i], true);
48	    assert.equal(m[i][0], true);
49	    assert.equal(m[6][i], true);
50	  }
51	  assert.equal(m[1][1], false);
52	});
53	
54	// TD-1 (3): remembered device for 30 days
55	test('remembered device is used only until trustedUntil, per username', () => {
56	  const now = new Date('2026-11-14T12:00:00Z');
57	  assert.equal(isStillRemembered({ token: 'abc', trustedUntil: '2026-12-14T12:00:00Z' }, now), true);
58	  assert.equal(isStillRemembered({ token: 'abc', trustedUntil: '2026-11-14T11:59:59Z' }, now), false);
59	  assert.equal(isStillRemembered({ token: '', trustedUntil: '2026-12-14T12:00:00Z' }, now), false);
60	  assert.equal(isStillRemembered(null, now), false);
61	  assert.equal(deviceKey(' Alice '), deviceKey('alice'));
62	  assert.notEqual(deviceKey('alice'), deviceKey('bob'));
63	});
64	
65	// UC-1 "View Daily Summary & Goals"
66	test('progress is clamped to 0..1 and safe for a zero goal', () => {
67	  assert.equal(progress(500, 2000), 0.25);
68	  assert.equal(progress(3000, 2000), 1);
69	  assert.equal(progress(-1, 2000), 0);
70	  assert.equal(progress(10, 0), 0);
71	});
72	
73	// FR-6 / Proposal §4: water from bottle size x refills
74	test('refill volume uses the bottle size', () => {
75	  assert.equal(refillVolume(500, 1), 500);
76	  assert.equal(refillVolume(750, 0.5), 375);
77	  assert.equal(refillVolume(500, -2), 0);
78	  assert.equal(refillVolume(Number.NaN, 1), 0);
79	});
80	
81	// FR-5 / SD-4 isEnabled(moduleId)
82	test('module flags: disabled module is reported, unknown or not-yet-loaded count as enabled', () => {
83	  const mods = [
84	    { moduleId: 'SOCIAL', name: 'Friends', enabled: false },
85	    { moduleId: 'NUTRITION', name: 'Nutrition', enabled: true },
