// FR-3 "view their own profile" + UC-3 "Edit Public Profile" (User.updateProfile, changePassword — §5.2);
// Student.setGoals(cal, water, steps) with NFR Safety "warning whenever an unsafe goal is set".
import React, { useEffect, useState } from 'react';
import { ScrollView, Text } from 'react-native';
import { api, ApiError } from '../api';
import { goalWarnings, parsePositiveInt } from '../logic';
import type { Profile } from '../types';
import { Banner, Button, Card, Field, s, Toggle } from '../ui';
import { useAsync } from '../useAsync';

export default function ProfileScreen({ onLogout, onChanged }: { onLogout: () => void; onChanged: () => void }) {
  const q = useAsync(() => api.profile(), []);
  const p = q.data;
  return (
    <ScrollView>
      {q.error ? <Banner kind="error">{q.error.message}</Banner> : null}
      {p ? (
        <>
          <PublicProfileCard profile={p} onSaved={q.setData} />
          {p.role === 'STUDENT' ? <GoalsCard profile={p} onSaved={(x) => { q.setData(x); onChanged(); }} /> : null}
          <PasswordCard />
        </>
      ) : null}
      <Button kind="danger" label="Sign out" onPress={onLogout} testID="logout" />
      <Text style={[s.muted, { textAlign: 'center', marginTop: 8 }]}>
        CometFit is a general wellness app and does not diagnose or treat any medical condition.
      </Text>
    </ScrollView>
  );
}

function PublicProfileCard({ profile, onSaved }: { profile: Profile; onSaved: (p: Profile) => void }) {
  const [name, setName] = useState(profile.displayName);
  const [isPublic, setPublic] = useState(profile.isPublic);
  const [msg, setMsg] = useState<string | null>(null);
  async function save() {
    try {
      onSaved(await api.updateProfile({ displayName: name, isPublic }));
      setMsg('Profile saved.');
    } catch (e) {
      setMsg((e as ApiError).message);
    }
  }
  return (
    <Card title="My profile">
      <Text style={s.body}>@{profile.username}</Text>
      <Text style={s.muted}>{profile.email} (private)</Text>
      <Field label="Display name (public)" value={name} onChangeText={setName} />
      <Toggle label="Public profile (visible to non-friends)" value={isPublic} onChange={setPublic} />
      {msg ? <Text style={s.muted}>{msg}</Text> : null}
      <Button label="Save profile" onPress={save} disabled={!name.trim()} />
    </Card>
  );
}

function GoalsCard({ profile, onSaved }: { profile: Profile; onSaved: (p: Profile) => void }) {
  const [cal, setCal] = useState(String(profile.calorieGoal ?? ''));
  const [water, setWater] = useState(String(profile.waterGoalMl ?? ''));
  const [steps, setSteps] = useState(String(profile.stepGoal ?? ''));
  const [bottle, setBottle] = useState(String(profile.bottleSizeMl ?? ''));
  const [serverWarnings, setServerWarnings] = useState<string[] | null>(null);
  const [error, setError] = useState<string | null>(null);

  const c = parsePositiveInt(cal, 10000), w = parsePositiveInt(water, 10000), st = parsePositiveInt(steps, 100000);
  const b = parsePositiveInt(bottle, 5000);
  const live = c && w && st ? goalWarnings(c, w, st) : [];
  useEffect(() => setServerWarnings(null), [cal, water, steps]);

  async function save() {
    setError(null);
    try {
      const r = await api.setGoals({ calorieGoal: c!, waterGoalMl: w!, stepGoal: st!, bottleSizeMl: b ?? undefined });
      setServerWarnings(r.warnings);
      onSaved(r.profile);
    } catch (e) {
      setError((e as ApiError).message);
    }
  }
  return (
    <Card title="Daily goals">
      <Field label="Calories (kcal)" value={cal} onChangeText={setCal} keyboardType="number-pad" testID="goal-cal" />
      <Field label="Water (ml)" value={water} onChangeText={setWater} keyboardType="number-pad" testID="goal-water" />
      <Field label="Steps" value={steps} onChangeText={setSteps} keyboardType="number-pad" />
      <Field label="My water bottle size (ml)" value={bottle} onChangeText={setBottle} keyboardType="number-pad" />
      {live.map((x) => (
        <Banner key={x} kind="warn">⚠ {x}</Banner>
      ))}
      {error ? <Banner kind="error">{error}</Banner> : null}
      {serverWarnings ? (
        <Banner kind={serverWarnings.length ? 'warn' : 'good'}>
          {serverWarnings.length ? 'Goals saved, but please review the warnings above.' : 'Goals saved.'}
        </Banner>
      ) : null}
      <Button label="Save goals" onPress={save} disabled={!c || !w || !st || (bottle !== '' && !b)} testID="save-goals" />
    </Card>
  );
}

function PasswordCard() {
  const [oldPw, setOld] = useState('');
  const [newPw, setNew] = useState('');
  const [msg, setMsg] = useState<string | null>(null);
  async function save() {
    try {
      await api.changePassword({ oldPassword: oldPw, newPassword: newPw });
      setMsg('Password changed.');
      setOld('');
      setNew('');
    } catch (e) {
      setMsg((e as ApiError).message);
    }
  }
  return (
    <Card title="Change password">
      <Field label="Current password" value={oldPw} onChangeText={setOld} secureTextEntry />
      <Field label="New password (8+ characters)" value={newPw} onChangeText={setNew} secureTextEntry />
      {msg ? <Text style={s.muted}>{msg}</Text> : null}
      <Button kind="secondary" label="Change password" onPress={save} disabled={!oldPw || newPw.length < 8} />
    </Card>
  );
}

// UC-4 Monitor and Control System — SD-4 "AdminDashboard (View)":
//   login (password + TOTP) -> authorize(admin, permissions) -> access granted          (UC-4 "Authorize Admin")
//   view uptime metrics -> getUptimeReport() -> uptime % and incident history            (FR-1)
//   disable module (e.g. Friends) -> disableModule(moduleId) ; re-enable -> enableModule  (FR-5)
//   alt [service down] send downtime alert                                                (UC-4 "Raise Downtime Alert")
import React, { useEffect, useState } from 'react';
import { ScrollView, Text, View } from 'react-native';
import { api, ApiError } from '../api';
import { formatDuration, shortTime } from '../logic';
import type { AdminAccess, DowntimeAlert, ModuleState, UptimeReport } from '../types';
import { Banner, Button, Card, colors, Row, s, Stat } from '../ui';

const REFRESH_MS = 10_000;

export default function AdminDashboard({ onLogout }: { onLogout: () => void }) {
  const [access, setAccess] = useState<AdminAccess | null>(null);
  const [report, setReport] = useState<UptimeReport | null>(null);
  const [alerts, setAlerts] = useState<DowntimeAlert[]>([]);
  const [modules, setModules] = useState<ModuleState[]>([]);
  const [hours, setHours] = useState(24);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState<string | null>(null);

  async function load() {
    try {
      const [a, r, al, m] = await Promise.all([api.adminAccess(), api.uptime(hours), api.alerts(), api.adminModules()]);
      setAccess(a);
      setReport(r);
      setAlerts(al);
      setModules(m);
      setError(null);
    } catch (e) {
      setError((e as ApiError).message);
    }
  }

  useEffect(() => {
    load();
    const t = setInterval(load, REFRESH_MS);
    return () => clearInterval(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [hours]);

  async function run(key: string, action: () => Promise<unknown>) {
    setBusy(key);
    try {
      await action();
      await load();
    } catch (e) {
      setError((e as ApiError).message);
    } finally {
      setBusy(null);
    }
  }

  return (
    <ScrollView contentContainerStyle={{ padding: 16, maxWidth: 900, width: '100%', alignSelf: 'center' }}>
      <Row style={{ justifyContent: 'space-between', marginBottom: 8 }}>
        <View>
          <Text style={s.h1}>CometFit Admin Dashboard</Text>
          {access ? (
            <Text style={s.muted}>
              {access.username} · {access.adminRole} · permissions: {access.permissions.join(', ')}
            </Text>
          ) : null}
        </View>
        <View style={{ width: 120 }}>
          <Button kind="secondary" label="Sign out" onPress={onLogout} />
        </View>
      </Row>
      {error ? <Banner kind="error">{error}</Banner> : null}

      {report ? (
        <Card title={`Server uptime (last ${report.rangeHours} h)`}>
          <Row>
            <Stat label="Overall uptime" value={`${report.overallUptimePercent.toFixed(2)}%`} />
            <Stat label="Current status" value={report.allUp ? 'All up' : 'Degraded'} />
            <Stat label="Check interval" value={`${report.checkIntervalSec}s`} />
          </Row>
          <Row>
            {[1, 24, 168].map((h) => (
              <View key={h} style={{ flex: 1 }}>
                <Button kind={hours === h ? 'primary' : 'secondary'} label={h === 168 ? '7 days' : `${h} h`} onPress={() => setHours(h)} />
              </View>
            ))}
            <View style={{ flex: 1 }}>
              <Button kind="secondary" label="Check now" onPress={() => run('check', api.checkNow)} busy={busy === 'check'} />
            </View>
          </Row>
          <View style={{ marginTop: 8 }}>
            {report.services.map((sv) => (
              <View key={sv.serviceName} style={[s.listItem, { flexDirection: 'row', alignItems: 'center' }]}>
                <View style={{ width: 12, height: 12, borderRadius: 6, backgroundColor: sv.up ? colors.good : colors.bad, marginRight: 8 }} />
                <View style={{ flex: 1 }}>
                  <Text style={s.body}>{sv.serviceName}</Text>
                  <Text style={s.muted}>
                    {sv.up ? 'UP' : 'DOWN'} · {sv.uptimePercent.toFixed(2)}% · {sv.lastResponseMs} ms · checked {shortTime(sv.lastCheckedAt)} · {sv.checks} checks
                  </Text>
                </View>
                <View style={{ width: 150 }}>
                  <Button
                    kind={sv.up ? 'secondary' : 'primary'}
                    label={sv.up ? 'Simulate outage' : 'End outage'}
                    onPress={() => run('o-' + sv.serviceName, () => api.simulateOutage(sv.serviceName, sv.up))}
                    busy={busy === 'o-' + sv.serviceName}
                  />
                </View>
              </View>
            ))}
            <Text style={s.muted}>"Simulate outage" is a demo stub that makes a component fail its health check.</Text>
          </View>
        </Card>
      ) : null}

      <Card title="Downtime alerts">
        {alerts.length === 0 ? <Text style={s.muted}>No alerts.</Text> : null}
        {alerts.slice(0, 10).map((a, i) => (
          <Banner key={a.raisedAt + i} kind={a.recovered ? 'good' : 'error'}>
            {shortTime(a.raisedAt)} — {a.message}
          </Banner>
        ))}
      </Card>

      {report ? (
        <Card title="Incident history">
          {report.incidents.length === 0 ? <Text style={s.muted}>No incidents in this period.</Text> : null}
          {report.incidents.slice(0, 20).map((i, idx) => (
            <Text key={i.serviceName + i.startedAt + idx} style={s.body}>
              {i.serviceName}: down from {shortTime(i.startedAt)} {i.ongoing ? '(ongoing)' : `to ${shortTime(i.endedAt)}`} · {formatDuration(i.durationSec)}
            </Text>
          ))}
        </Card>
      ) : null}

      <Card title="App modules">
        <Text style={s.muted}>
          Turning a module off shows students a maintenance notice for that part of the app; everything else keeps working.
        </Text>
        {modules.map((m) => (
          <View key={m.moduleId} style={[s.listItem, { flexDirection: 'row', alignItems: 'center' }]}>
            <View style={{ flex: 1 }}>
              <Text style={s.body}>{m.name}</Text>
              <Text style={[s.muted, { color: m.enabled ? colors.good : colors.bad }]}>{m.enabled ? 'Enabled' : 'Disabled (maintenance)'}</Text>
            </View>
            <View style={{ width: 130 }}>
              <Button
                kind={m.enabled ? 'danger' : 'primary'}
                label={m.enabled ? 'Disable' : 'Re-enable'}
                onPress={() => run('m-' + m.moduleId, () => (m.enabled ? api.disableModule(m.moduleId) : api.enableModule(m.moduleId)))}
                busy={busy === 'm-' + m.moduleId}
                testID={`toggle-${m.moduleId}`}
              />
            </View>
          </View>
