/** Local calendar date as YYYY-MM-DD (the server's `?date=` format). */
export function isoDate(d: Date): string {
  const p = (n: number) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
}

/** The last n calendar days ending today, oldest first (Week = 7, Month = 30; A-45). */
export function lastNDates(n: number, today: Date = new Date()): string[] {
  const out: string[] = [];
  for (let i = n - 1; i >= 0; i--) {
    out.push(isoDate(new Date(today.getFullYear(), today.getMonth(), today.getDate() - i)));
  }
  return out;
}

/** One line of the prototype's "Today's log": meals (F) and water (W) together, newest first. */
export interface LogLine { kind: 'food' | 'water'; key: string; name: string; at: string; value: number; meal?: MealEntry }
export function mergeTodayLog(meals: MealEntry[], water: WaterEntry[]): LogLine[] {
  const lines: LogLine[] = [
    ...meals.map((m, i) => ({ kind: 'food' as const, key: `m${m.entryId ?? i}`, name: m.foodName, at: m.loggedAt, value: m.calories, meal: m })),
    ...water.map((w) => ({ kind: 'water' as const, key: `w${w.entryId}`, name: 'Water', at: w.loggedAt, value: w.volumeMl })),
  ];
  return lines.sort((a, b) => Date.parse(b.at) - Date.parse(a.at));
}

/** Totals over a Week / Month of daily summaries. */
export interface PeriodTotals { days: number; calories: number; waterMl: number; avgCalories: number; avgWaterMl: number; daysLogged: number; daysWaterGoal: number }
export function periodTotals(days: Pick<DailySummary, 'calories' | 'waterMl' | 'waterGoalMl' | 'mealCount'>[]): PeriodTotals {
  const calories = days.reduce((a, d) => a + d.calories, 0);
  const waterMl = days.reduce((a, d) => a + d.waterMl, 0);
  const n = days.length;
  return {
    days: n,
    calories,
    waterMl,
    avgCalories: n ? Math.round(calories / n) : 0,
    avgWaterMl: n ? Math.round(waterMl / n) : 0,
    daysLogged: days.filter((d) => d.mealCount > 0).length,
    daysWaterGoal: days.filter((d) => d.waterGoalMl > 0 && d.waterMl >= d.waterGoalMl).length,
  };
}

/** "12:30 PM" as in the prototype. */
export function clockTime(iso: string): string {
  return new Date(iso).toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });
}

